import java.util.*;
class DenseRiverBranchesTest{
 static TerraForge.World world(int n,int ox,int oz){var w=new TerraForge.World(n,62,83);Arrays.fill(w.height,92);var e=w.environment;e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];e.snow=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)if(oz+z>=508&&oz+z<=516){int i=z*n+x;e.height[i]=87;e.water[i]=90;e.river[i]=1;}return w;}
 public static void main(String[]args){int n=1024;var segments=new ArrayList<RiverRibbon.Segment>();for(int x=40;x<960;x+=8)segments.add(new RiverRibbon.Segment(new RiverRibbon.Point(x,512,5,90,150000),new RiverRibbon.Point(x+8,512,5,90,150000),3,.8,0));var sparse=new RiverRibbon.Network(segments);var dense=sparse.options(4,List.of());if(dense.islands.size()<sparse.islands.size()*2)throw new AssertionError("Split density has no effect");var terrain=EnvironmentMap.filled(n*n,92);var branches=RiverSideBranches.generate(dense,terrain,terrain,n,n,62,4,8472,.18);if(branches.size()!=4)throw new AssertionError("Missing side branches: "+branches.size());dense=dense.options(4,branches);var full=world(n,0,0);RiverSideBranches.carve(full.environment,n,0,0,62,dense,null);for(var branch:branches){var first=branch.points().get(1);var tip=branch.points().get(branch.points().size()-1);int stem=(int)Math.round(first.z())*n+(int)Math.round(first.x()),end=(int)Math.round(tip.z())*n+(int)Math.round(tip.x());if(full.environment.waterY(stem,62)<=Math.round(full.height[stem]))throw new AssertionError("Disconnected branch stem");if(full.environment.waterY(end,62)>Math.round(full.height[end]))throw new AssertionError("Branch does not dry out");if(tip.radius()>=first.radius())throw new AssertionError("Branch does not taper");}
 for(int rz=0;rz<2;rz++)for(int rx=0;rx<2;rx++){var tile=world(512,rx*512,rz*512);RiverSideBranches.carve(tile.environment,512,rx*512,rz*512,62,dense,null);for(int z=0;z<512;z++)for(int x=0;x<512;x++){int i=z*512+x,j=(rz*512+z)*1024+rx*512+x;if(tile.height[i]!=full.height[j]||tile.environment.water[i]!=full.environment.water[j]||tile.environment.material[i]!=full.environment.material[j])throw new AssertionError("Side branch tile seam");}}
 var remapped=dense.remap(.9,3,62);if(remapped.sideBranches.size()!=4||remapped.splitDensity!=4)throw new AssertionError("Graph remap dropped branches/density");System.out.println("PASS: split density "+sparse.islands.size()+" -> "+dense.islands.size()+"; four connected tapered wet stems with dry ends; exact four-tile seam agreement and graph propagation");}
}
